// ── HAVAN · STORY scene (helicopter + man + caption) ──
const B = sc.sky1 || "#0b5cab";
const Y = sc.acc  || "#f4b400";
const G = sc.ground || "#1f7a4d";
const deep = sc.sky2 || "#093f78";
const cream = "#fffdf5";
const white = "#ffffff";
const ww = w / 900;
const blueTrousers = B;
const yellowShirt = Y;

const sin = (t,amp=1,freq=1,phase=0) => Math.sin(t*freq+phase)*amp;
const cos = (t,amp=1,freq=1,phase=0) => Math.cos(t*freq+phase)*amp;

// ── defs (filters + gradients) ──
svg += `<defs>
  <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
    <feGaussianBlur stdDeviation="2.5" result="b"/>
    <feMerge><feMergeNode in="b"/><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <filter id="softGlow" x="-50%" y="-50%" width="200%" height="200%">
    <feGaussianBlur stdDeviation="1.5" result="b"/>
    <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
  </filter>
  <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
    <feDropShadow dx="0" dy="2" stdDeviation="3" flood-color="#000000" flood-opacity="0.3"/>
  </filter>
  <filter id="blurFar"><feGaussianBlur stdDeviation="1.8"/></filter>
  <linearGradient id="skyGrad" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${B}"/><stop offset="100%" stop-color="${deep}"/>
  </linearGradient>
  <linearGradient id="buildGrad" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${B}" stop-opacity="0.9"/><stop offset="100%" stop-color="${deep}" stop-opacity="0.95"/>
  </linearGradient>
  <radialGradient id="sunGrad" cx="50%" cy="50%" r="50%">
    <stop offset="0%" stop-color="${Y}" stop-opacity="0.9"/><stop offset="70%" stop-color="${Y}" stop-opacity="0.2"/><stop offset="100%" stop-color="${Y}" stop-opacity="0"/>
  </radialGradient>
  <linearGradient id="flagGrad" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="${G}" stop-opacity="0.85"/><stop offset="100%" stop-color="${deep}" stop-opacity="0.9"/>
  </linearGradient>
  <linearGradient id="capGrad" x1="0" y1="0" x2="0" y2="1">
    <stop offset="0%" stop-color="#06121d" stop-opacity="0.82"/><stop offset="100%" stop-color="#06121d" stop-opacity="0.66"/>
  </linearGradient>
</defs>`;

// ── BACKGROUND: layered hills ──
const hY = bY - 6;
svg += `<path d="M0 ${hY} Q ${w*0.25} ${hY-40*ww} ${w*0.5} ${hY-14} T ${w} ${hY-26} L ${w} ${bY} L 0 ${bY} Z" fill="${G}" opacity="0.3" filter="url(#blurFar)"/>`;
svg += `<path d="M0 ${hY-10} Q ${w*0.3} ${hY-60*ww} ${w*0.65} ${hY-22} T ${w} ${hY-40} L ${w} ${bY} L 0 ${bY} Z" fill="url(#skyGrad)" opacity="0.2" filter="url(#blurFar)"/>`;

// ── SUN / MOON ──
const sunX=w*0.82, sunY=h*0.20, sunR=(18+4*w1)*ww;
if(!isN){
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR*1.8}" fill="url(#sunGrad)"/>`;
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR}" fill="${Y}" filter="url(#glow)"/>`;
}else{
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR*1.6}" fill="#ffffff" opacity="0.15" filter="url(#glow)"/>`;
  svg += `<circle cx="${sunX}" cy="${sunY}" r="${sunR}" fill="#f4f7fb"/>`;
  svg += `<circle cx="${sunX+sunR*0.5}" cy="${sunY-sunR*0.4}" r="${sunR*0.9}" fill="${deep}"/>`;
}

// ── HELICOPTER (flies left→right on a loop via w2 oscillator) ──
const heliSpan = w*0.82;
const heliX = w*0.06 + heliSpan * (0.5 - 0.5*cos(w2*Math.PI*2)); // smooth 0..1..0 across full w2 cycle
const heliY = h*0.30 + sin(w2*Math.PI*2, 14*ww);
const rotorBlade = 22*ww * Math.abs(cos(mt*8)); // blur-ish spin illusion
const heliS = 1.0;
svg += `<g transform="translate(${heliX.toFixed(1)},${heliY.toFixed(1)}) scale(${heliS})">
  <ellipse cx="0" cy="-2" rx="${30*ww}" ry="${13*ww}" fill="${deep}" filter="url(#shadow)"/>
  <rect x="${20*ww}" y="${-12*ww}" width="${16*ww}" height="${14*ww}" rx="3" fill="${deep}"/>
  <circle cx="${34*ww}" cy="${-5*ww}" r="${4*ww}" fill="${Y}" opacity="0.9"/>
  <rect x="${-34*ww}" y="${-8*ww}" width="${14*ww}" height="${6*ww}" rx="2" fill="${deep}"/>
  <line x1="0" y1="${-12*ww}" x2="0" y2="${-26*ww}" stroke="#2b3a47" stroke-width="${2*ww}"/>
  <ellipse cx="0" cy="${-28*ww}" rx="${rotorBlade.toFixed(1)}" ry="${3*ww}" fill="#243042" opacity="0.85"/>
  <ellipse cx="0" cy="${-28*ww}" rx="${3*ww}" ry="${rotorBlade.toFixed(1)}" fill="#243042" opacity="0.55"/>
  <circle cx="${8*ww}" cy="${10*ww}" r="${2*ww}" fill="${Y}" filter="url(#glow)"/>
</g>`;

// ── MIDGROUND: MEGALOJA ──
const storeW = w*0.46, storeH = h*0.34, storeX = w*0.06, storeY = bY - storeH;
svg += `<rect x="${storeX}" y="${storeY}" width="${storeW}" height="${storeH}" rx="10" fill="url(#buildGrad)" filter="url(#shadow)"/>`;
svg += `<rect x="${storeX}" y="${storeY}" width="${storeW}" height="${storeH*0.16}" rx="10" fill="${deep}"/>`;
const cols = 7;
for(let i=0;i<cols;i++){
  const cx = storeX + storeW*(0.10 + 0.80*i/(cols-1));
  svg += `<rect x="${cx-6}" y="${storeY+storeH*0.22}" width="12" height="${storeH*0.6}" rx="3" fill="url(#buildGrad)" opacity="0.9" filter="url(#shadow)"/>`;
}
const signW = storeW*0.42, signH = storeH*0.08, signX = storeX + (storeW - signW)/2, signY = storeY + storeH*0.07;
svg += `<rect x="${signX}" y="${signY}" width="${signW}" height="${signH}" rx="4" fill="${Y}" filter="url(#glow)"/>`;
svg += `<text x="${storeX+storeW*0.5}" y="${storeY+storeH*0.135}" font-family="Georgia,serif" font-size="${storeH*0.07}" font-weight="700" fill="${deep}" text-anchor="middle">HAVAN</text>`;
const wrows=2, wcols=6;
for(let r=0;r<wrows;r++)for(let c=0;c<wcols;c++){
  const wx = storeX + storeW*(0.14 + 0.72*c/(wcols-1));
  const wy = storeY + storeH*(0.38 + 0.30*r);
  const glow = isN ? 0.6+0.4*w1 : 0.75+0.25*w2;
  svg += `<rect x="${wx-7}" y="${wy-7}" width="14" height="14" rx="2" fill="${G}" opacity="${glow.toFixed(2)}" filter="url(#softGlow)"/>`;
}

// ── DISTRIBUTION CENTER ──
const dcW=w*0.22, dcX=w*0.62, dcY=bY-dcW*0.7;
svg += `<rect x="${dcX}" y="${dcY}" width="${dcW}" height="${dcW*0.7}" rx="6" fill="${deep}" filter="url(#shadow)"/>`;
svg += `<path d="M${dcX} ${dcY} h${dcW} l-${dcW*0.5} -${dcW*0.30} Z" fill="${deep}" opacity="0.7"/>`;

// ── FLAG ──
const pX = w*0.30, pTop = h*0.30;
svg += `<rect x="${pX-3}" y="${pTop}" width="6" height="${bY-pTop}" fill="#cfd8e3" filter="url(#shadow)"/>`;
const fW=w*0.20, fH=h*0.13, fx=pX+3, fy=pTop+4;
let flagPath = `M`;
const segs=20;
for(let i=0;i<=segs;i++){
  const t=i/segs;
  const px = fx+fW*t;
  const wave = sin(t*8 + mt*1.6, fH*0.12) * sin(t*Math.PI);
  const py = fy + wave;
  flagPath += `${px.toFixed(1)},${py.toFixed(1)} `;
}
flagPath += `L${fx+fW} ${fy+fH} L${fx} ${fy+fH} Z`;
svg += `<path d="${flagPath}" fill="url(#flagGrad)" filter="url(#shadow)"/>`;
const cxF = fx+fW*0.5, cyF = fy+fH*0.5, dR = fH*0.30 + sin(mt*0.7, 2);
svg += `<path d="M${cxF} ${cyF-dR} L${cxF+dR} ${cyF} L${cxF} ${cyF+dR} L${cxF-dR} ${cyF} Z" fill="${Y}" filter="url(#glow)"/>`;

// ── MAN: yellow shirt + blue trousers (walks slowly via w1, breathing via w3) ──
const manX = w*0.50 + sin(w1*Math.PI*2, w*0.18);
const manBase = bY - 2;
const bob = sin(mt*2.4, 2*ww);
const mS = (6*ww);
svg += `<g transform="translate(${manX.toFixed(1)},${(manBase+bob).toFixed(1)})">
  <ellipse cx="0" cy="${2*mS}" rx="${5*mS}" ry="${1.6*mS}" fill="#000" opacity="0.18"/>
  <rect x="${-2.2*mS}" y="${-9*mS}" width="${4.4*mS}" height="${8*mS}" rx="${2*mS}" fill="${blueTrousers}" filter="url(#shadow)"/>
  <rect x="${-3*mS}" y="${-15*mS}" width="${6*mS}" height="${7*mS}" rx="${2.4*mS}" fill="${yellowShirt}" filter="url(#glow)"/>
  <circle cx="0" cy="${-18*mS}" r="${3*mS}" fill="#e9c39a"/>
  <circle cx="0" cy="${-18.6*mS}" r="${3*mS}" fill="#3a2f25" opacity="0.9"/>
  <rect x="${-2*mS}" y="${-7.2*mS}" width="${1.3*mS}" height="${6*mS}" rx="${0.6*mS}" fill="${blueTrousers}"/>
  <rect x="${0.7*mS}" y="${-7.2*mS}" width="${1.3*mS}" height="${6*mS}" rx="${0.6*mS}" fill="${blueTrousers}"/>
</g>`;

// ── FOREGROUND: families (breathing) ──
const fcols=[B,Y,G];
for(let i=0;i<4;i++){
  const dx = w*(0.10+0.18*i) + sin(mt*0.8+i, 4);
  const dy = bY-2 - (8+ (i%3)*6);
  const scale = 1 + sin(mt*1.3+i, 0.08);
  svg += `<circle cx="${dx.toFixed(1)}" cy="${dy}" r="${(5*scale).toFixed(1)}" fill="${fcols[i%3]}" opacity="0.9" filter="url(#shadow)"/>`;
}

// ── CAPTION (short story) ──
const capY = h*0.90;
const capW = w*0.92, capX = w*0.04;
svg += `<rect x="${capX}" y="${capY}" width="${capW}" height="${h*0.075}" rx="10" fill="url(#capGrad)" filter="url(#shadow)"/>`;
svg += `<rect x="${capX}" y="${capY}" width="${w*0.012}" height="${h*0.075}" rx="3" fill="${Y}"/>`;
svg += `<text x="${capX + w*0.03}" y="${capY + h*0.032}" font-family="Georgia,serif" font-size="${h*0.022}" font-style="italic" fill="${white}">Orgulho Brasileiro, de norte a sul da nossa linda terra</text>`;
svg += `<text x="${capX + w*0.03}" y="${capY + h*0.060}" font-family="Plus Jakarta Sans, sans-serif" font-size="${h*0.020}" fill="${Y}">...pena que tão corrupta.</text>`;

return svg;
